CREATE TABLE r AS SELECT a,b,sum(c)OVER(ORDER BY a GROUPS BETWEEN CURRENT ROW AND 0 FOLLOWING EXCLUDE CURRENT ROW) AS x1,sum(c)OVER(ORDER BY a GROUPS BETWEEN CURRENT ROW AND 0 FOLLOWING) AS x2,sum(c)OVER(ORDER BY a,b GROUPS BETWEEN CURRENT ROW AND 0 FOLLOWING EXCLUDE CURRENT ROW) AS x3,sum(c)OVER(ORDER BY a,b GROUPS BETWEEN CURRENT ROW AND 0 FOLLOWING) AS x4 FROM t3;